/**
 * Async mock data access — replaceable by a real API later.
 * Pure filtering lives in `catalog-query`; this adds artificial latency only.
 */
export async function getDrugs(
  params: DrugQueryParams = {},
): Promise<DrugQueryResult> {
  await delay(180)
  return applyDrugQuery(MOCK_DRUGS, params)
}

/**
 * Pure mock TTAC lookup — no network. Special codes:
 * - known GTIN → found
 * - `ERROR` / `خطا` → error
 * - anything else → not_found
 */
export async function lookupTtac(rawQuery: string): Promise<TtacLookupState> {
  await delay(420)
  const query = rawQuery.trim()
  if (!query) {
    return { status: 'error', message: 'کد GTIN یا IRC را وارد کنید.' }
  }
  if (/^(ERROR|خطا)$/i.test(query)) {
    return {
      status: 'error',
      message: 'ارتباط با سامانه تیتک برقرار نشد. دوباره تلاش کنید.',
    }
  }
  const product = TTAC_CATALOG[query]
  if (product) return { status: 'found', product }
  return { status: 'not_found' }
}

export const FIXTURE_DRUGS = MOCK_DRUGS
